/**
 * InteractiveAnnotatedScreenshot — product-tour style guide visuals.
 * Works with markup generated by scripts/build-guide-pages.py
 */
(function () {
  var CIRCLED = ['①', '②', '③', '④', '⑤', '⑥', '⑦', '⑧', '⑨'];

  function parseTourData(root) {
    var el = root.querySelector('.interactive-tour__data');
    if (!el) return [];
    try {
      return JSON.parse(el.textContent);
    } catch (e) {
      return [];
    }
  }

  function renderPanel(ann, index) {
    var label = CIRCLED[index] || String(index + 1);
    var example = ann.example
      ? '<p class="interactive-tour__example"><strong>Example:</strong> ' + ann.example + '</p>'
      : '';
    return (
      '<p class="interactive-tour__step-label" aria-hidden="true">' +
      label +
      '</p>' +
      '<h3 class="interactive-tour__panel-title">' +
      ann.title +
      '</h3>' +
      '<p class="interactive-tour__panel-desc">' +
      ann.description +
      '</p>' +
      example
    );
  }

  function initTour(root) {
    var annotations = parseTourData(root);
    if (!annotations.length) return;

    var markers = root.querySelectorAll('[data-tour-marker]');
    var panel = root.querySelector('[data-tour-panel]');
    if (!panel || !markers.length) return;

    var active = 0;

    function setActive(index) {
      if (index < 0 || index >= annotations.length) return;
      active = index;
      markers.forEach(function (btn, i) {
        var isActive = i === index;
        btn.classList.toggle('is-active', isActive);
        btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
      });

      panel.classList.add('is-updating');
      window.setTimeout(function () {
        panel.innerHTML = renderPanel(annotations[index], index);
        panel.classList.remove('is-updating');
      }, 120);
    }

    markers.forEach(function (btn) {
      btn.addEventListener('click', function () {
        var idx = parseInt(btn.getAttribute('data-tour-marker'), 10);
        setActive(idx);
      });
    });

    root.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
        e.preventDefault();
        setActive(Math.min(active + 1, annotations.length - 1));
        markers[active].focus();
      }
      if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
        e.preventDefault();
        setActive(Math.max(active - 1, 0));
        markers[active].focus();
      }
    });

    panel.innerHTML = renderPanel(annotations[0], 0);
    markers[0].classList.add('is-active');
    markers[0].setAttribute('aria-pressed', 'true');
  }

  function initAll() {
    document.querySelectorAll('.interactive-tour').forEach(initTour);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }
})();
